import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class FriendActivityScreen extends StatelessWidget{FriendActivityScreen({super.key});final repo=FootballRepository();@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Friends Activity')),body:FutureBuilder<List<dynamic>>(future:repo.friendActivity(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('No friend activity yet'));return ListView.builder(itemCount:s.data!.length,itemBuilder:(c,i){final x=s.data![i];return ListTile(leading:const CircleAvatar(child:Icon(Icons.people)),title:Text('${x['user']?['username']??x['user']?['name']??''}'),subtitle:Text('${x['type']??''}'),trailing:Text('${x['created_at']??''}'.split('T').first));});}));}
